cat > $TMPDIR/scan_pull.py << 'PYEOF'
import re, os, sys, subprocess

root = sys.argv[1] if len(sys.argv) > 1 else '.'
pull_re = re.compile(r'\b(pskb_may_pull|pskb_may_pull_reason|__pskb_pull_tail|pskb_pull|pskb_pull_tail)\s*\(')
# expressions that derive a pointer into skb data
derive_re = re.compile(
    r'=\s*(?:\(\s*([A-Za-z_][A-Za-z0-9_]*)\s*\*\s*\)\s*)?'
    r'(skb_header_pointer|__skb_header_pointer)\s*\('
)
ptr_derive_re = re.compile(
    r'=\s*(?:\(?\s*(?:const\s+)?(?:struct\s+)?[A-Za-z_][A-Za-z0-9_]*\s*\*+\s*\)?\s*)?'
    r'((?:skb|nskb|skb2|skb_in|skb_out|skbs|new_skb|seg|frag)\b[^;=]*)'
)

def func_bounds(lines, idx):
    # find start: search backwards for line at col 0 that looks like function def start '{'
    start = 0
    for i in range(idx, -1, -1):
        if lines[i].startswith('{'):
            # find function signature line above
            j = i-1
            while j >= 0 and not re.match(r'^[A-Za-z_].*\)\s*$', lines[j]) and lines[j].strip() and not lines[j].startswith('#'):
                j -= 1
            start = max(j, 0)
            break
    # find end: matching brace from start brace
    depth = 0
    i = start
    while i < len(lines):
        depth += lines[i].count('{') - lines[i].count('}')
        if depth == 0 and i > start and '{' in ''.join(lines[start:i+1]):
            return start, i
        i += 1
    return start, len(lines)-1

results = []
for dirpath, dirnames, filenames in os.walk(root):
    for fn in filenames:
        if not (fn.endswith('.c') or fn.endswith('.h')):
            continue
        path = os.path.join(dirpath, fn)
        try:
            with open(path, 'r', errors='replace') as f:
                lines = f.readlines()
        except Exception:
            continue
        for i, line in enumerate(lines):
            if pull_re.search(line):
                # also detect skb_pull / __pskb_pull which move data pointer
                try:
                    s, e = func_bounds(lines, i)
                except Exception:
                    continue
                func = ''.join(lines[s:e+1])
                # find variables assigned from skb_header_pointer before pull line
                hdr_ptrs = {}
                for j in range(s, i):
                    m = derive_re.search(lines[j])
                    if m:
                        # get LHS var
                        lhs = lines[j].split('=')[0].strip().split()[-1].strip('* ')
                        hdr_ptrs.setdefault(lhs, j)
                # find ptrs assigned directly from skb->data / header accessors before pull
                data_ptrs = {}
                for j in range(s, i):
                    m = re.search(r'([A-Za-z_][A-Za-z0-9_]*)\s*=\s*[^;]*(?:skb|nskb|skb2|seg)->data\b', lines[j])
                    if m:
                        data_ptrs.setdefault(m.group(1), j)
                    m2 = re.search(r'([A-Za-z_][A-Za-z0-9_]*)\s*=\s*[^;]*\b(skb_network_header|skb_transport_header|skb_mac_header|skb_push|skb_pull)\s*\(', lines[j])
                    if m2:
                        data_ptrs.setdefault(m2.group(1), j)
                # check usage after pull
                used_after = []
                for var, dl in list(hdr_ptrs.items()) + list(data_ptrs.items()):
                    var_re = re.compile(r'\b' + re.escape(var) + r'\b')
                    for j in range(i+1, e+1):
                        l = lines[j]
                        if var_re.search(l) and not re.search(r'=\s*[^;]*' + re.escape(var) + r'\s*;', l + ';'):
                            # skip pure reassignment of var
                            if re.match(r'^\s*(?:\*?\s*)?' + re.escape(var) + r'\s*=', l):
                                continue
                            used_after.append((var, dl, j, lines[j].rstrip()))
                            break
                if used_after:
                    results.append((path, i+1, s+1, e+1, lines[i].strip(), used_after))

for path, ln, s, e, pull, uses in results:
    print('='*100)
    print(f"{path}:{ln} (func {s}-{e}) PULL: {pull}")
    for var, dl, ul, uline in uses:
        print(f"  var {var}: saved@{dl+1} used@{ul+1}: {uline.strip()}")
