            depth = 0; j = start
            while j < n:
                depth += lines[j].count('{') - lines[j].count('}')
                if depth == 0 and j >= start: return j
                j += 1
            return n-1
        brace_lines = [k for k in range(n) if lines[k].startswith('{')]
